#!/usr/bin/env bash\nset -e\n\n# Build the Docker image (quietly)\ndocker build -t test-fortune . > /dev/null\n\n# Run the container with a known input\noutput=$(docker run --rm test-fortune "test")\n\nexpected="Stars align over the wasteland."\n\nif [ "$output" = "$expected" ]; then\n  echo "PASS"\n  exit 0\nelse\n  echo "FAIL: expected '$expected' but got '$output'"\n  exit 1\nfi\n
